parameters.jsCode:
const bloodGroup = $fromAI('bloodGroup', 'Blood group required') || 'O+';
const district = $fromAI('district', 'District name') || 'Jaffna';
const recipientCount = $fromAI('donorCount', 'Number of donors matched') || 5;
const hospital = $fromAI('hospital', 'Destination hospital') || 'Teaching Hospital Jaffna';

return {
  status: 'DISPATCHED',
  alertId: 'alert-' + Date.now(),
  channel: 'EMAIL_AND_WHATSAPP',
  priority: 'CRITICAL_URGENT',
  notifiedCount: Number(recipientCount),
  hospital,
  bloodGroup,
  district,
  dispatchedAt: new Date().toISOString(),
  message: `24/7 AI Agent dispatched emergency blood alerts for ${bloodGroup} at ${hospital}, ${district}. Donors are directed via LifeLink Live GPS Navigation.`
};
